const upsertParticipant = `-- name: UpsertParticipant :exec
INSERT INTO gameplay_participants (gameplay_id, user_id, status)
VALUES ($1, $2, $3)
ON CONFLICT (gameplay_id, user_id) DO UPDATE SET status = EXCLUDED.status, updated_at = now()
`

type UpsertParticipantParams struct {
	GameplayID string
	UserID     string
	Status     string
}

func (q *Queries) UpsertParticipant(ctx context.Context, arg UpsertParticipantParams) error {
	_, err := q.db.Exec(ctx, upsertParticipant, arg.GameplayID, arg.UserID, arg.Status)
	return err
}
